//! Scaffold a fresh single-package layout (manifest + minimal C++
//! source tree) at a target directory.
//!
//! Used by both `cabin init` (initialize the current directory)
//! and `cabin new <path>` (create a new directory and initialize
//! it).  The two CLI surfaces call into [`scaffold`] so the
//! generated bytes stay identical across them.
//!
//! The scaffold kind ([`ScaffoldKind::Binary`] /
//! [`ScaffoldKind::Library`]) selects between an `executable`
//! and a `library` target layout.

use std::path::{Path, PathBuf};

use cabin_core::{PackageName, ValidationError};
use cabin_fs::write_atomic;
use thiserror::Error;

/// Conventional manifest filename used by every Cabin command.
pub const MANIFEST_FILENAME: &str = "cabin.toml";

/// Package name used when no `--name` is given and the target
/// directory's final component is not a usable package name.
pub const FALLBACK_PACKAGE_NAME: &str = "cabin-package";

/// Minimal C++ executable body emitted alongside a binary-package
/// manifest.
pub const BINARY_MAIN_CC_TEMPLATE: &str = "#include <iostream>\n\nint main() {\n    std::cout << \"Hello from Cabin\\n\";\n    return 0;\n}\n";

/// Conventional `.gitignore` body emitted by `cabin new` and by
/// `cabin init` when one does not already exist.  Cabin's default
/// build directory is `build/`; `dist/` is the default packaging
/// output directory. `cabin.lock` is not ignored: it is committed so
/// collaborators converge on the same resolution (see
/// `docs/lockfile.md`).
pub const GITIGNORE_TEMPLATE: &str = "/build/\n/dist/\n";

/// What scaffold kind to generate.  Binary produces an `executable`
/// target; Library produces a `library` target with a public header
/// under `include/` and an implementation source under `src/`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ScaffoldKind {
    /// Single-target binary (`executable`).  This is the
    /// default both for `cabin new` and `cabin init`.
    #[default]
    Binary,
    /// Single-target library (`library`) with a minimal
    /// public header and implementation source.
    Library,
}

impl ScaffoldKind {
    /// Short human-readable label used in reporter output.
    /// `cabin new` / `cabin init` render it unquoted in the
    /// ``Created <label> `<name>` package`` status line.
    pub fn label(self) -> &'static str {
        match self {
            Self::Binary => "binary (application)",
            Self::Library => "library",
        }
    }
}

/// Typed request for [`scaffold`].  Construct with
/// [`ScaffoldRequest::new`] for the default (binary, no
/// `.gitignore`) and adjust before passing to the scaffold
/// function.
#[derive(Debug, Clone, Copy)]
pub struct ScaffoldRequest<'a> {
    /// Directory the scaffold writes into.  Must already exist
    /// and be a directory.  Callers that want to create a
    /// brand-new directory (`cabin new <path>`) are responsible
    /// for creating it first so they can decide how to clean up
    /// on failure.
    pub dest_dir: &'a Path,
    /// Explicit package name override, used verbatim: it must already
    /// be a valid bare package name.  When `None`, the default is the
    /// final component of `dest_dir`, ASCII-lowercased, falling back
    /// to [`FALLBACK_PACKAGE_NAME`] when that is not a valid package
    /// name.
    pub name_override: Option<&'a str>,
    /// Scaffold kind.  Selects between binary and library
    /// layouts.
    pub kind: ScaffoldKind,
    /// Whether to write a `.gitignore` when one does not already
    /// exist. `cabin new` and `cabin init` both pass `true`.
    pub emit_gitignore: bool,
}

impl<'a> ScaffoldRequest<'a> {
    /// Build a default request that targets `dest_dir`.  The
    /// kind defaults to [`ScaffoldKind::Binary`], no
    /// `.gitignore` is emitted, and the package name is derived
    /// from the target directory.
    pub fn new(dest_dir: &'a Path) -> Self {
        Self {
            dest_dir,
            name_override: None,
            kind: ScaffoldKind::Binary,
            emit_gitignore: false,
        }
    }

    /// Set the package name override.
    #[must_use]
    pub fn with_name(mut self, name: Option<&'a str>) -> Self {
        self.name_override = name;
        self
    }

    /// Set the scaffold kind.
    #[must_use]
    pub fn with_kind(mut self, kind: ScaffoldKind) -> Self {
        self.kind = kind;
        self
    }

    /// Enable `.gitignore` emission (only writes the file when
    /// none exists at the destination).
    #[must_use]
    pub fn with_gitignore(mut self, emit: bool) -> Self {
        self.emit_gitignore = emit;
        self
    }
}

/// Outcome of a successful [`scaffold`] call.
#[derive(Debug, Clone)]
pub struct ScaffoldReport {
    /// Validated package name written into the manifest.
    pub name: PackageName,
    /// Scaffold kind that was generated.
    pub kind: ScaffoldKind,
    /// Files newly written by this call, in deterministic order.
    /// Preserved pre-existing files (sources, the library header,
    /// `.gitignore`) are not listed here.
    pub files_created: Vec<PathBuf>,
}

/// Errors produced while scaffolding a new package layout.
#[derive(Debug, Error)]
pub enum ScaffoldError {
    /// The explicit package name is not a valid package name.
    #[error(transparent)]
    InvalidName(#[from] ValidationError),

    /// The explicit package name is scoped; the scaffold uses the name
    /// as its target key and file stems, which have no `/`.
    #[error(
        "package name {name:?} is scoped, but `cabin new` and `cabin init` scaffold a bare name; pass `--name {base}` and add the scope to `[package].name` before publishing"
    )]
    ScopedName { name: String, base: String },

    /// A `cabin.toml` already exists at the target directory.
    #[error("{MANIFEST_FILENAME} already exists at {}", path.display())]
    ManifestAlreadyExists { path: PathBuf },

    /// Filesystem IO failure when creating directories or writing
    /// generated files.
    #[error("failed to write {}: {source}", path.display())]
    Io {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },
}

/// Scaffold a fresh single-package layout into `request.dest_dir`.
///
/// On success a `cabin.toml` plus the kind-specific source tree
/// are written into the destination directory, and a
/// [`ScaffoldReport`] is returned describing what was produced.
///
/// Pre-existing user files are never overwritten:
/// - an existing `cabin.toml` is rejected with
///   [`ScaffoldError::ManifestAlreadyExists`];
/// - an existing `src/main.cc`, public header, or implementation
///   source is preserved unchanged;
/// - an existing `.gitignore` is preserved unchanged regardless
///   of `request.emit_gitignore`.
///
/// # Errors
/// Returns [`ScaffoldError::InvalidName`] or
/// [`ScaffoldError::ScopedName`] when the explicit package name is
/// unusable, [`ScaffoldError::ManifestAlreadyExists`]
/// when a `cabin.toml` is already present at the destination, and
/// [`ScaffoldError::Io`] when creating directories or writing a
/// generated file fails.
pub fn scaffold(request: ScaffoldRequest<'_>) -> Result<ScaffoldReport, ScaffoldError> {
    let raw_name = request.name_override.map_or_else(
        || default_package_name_from_dir(request.dest_dir),
        str::to_owned,
    );
    let name = validate_package_name(raw_name)?;

    let manifest_path = request.dest_dir.join(MANIFEST_FILENAME);
    if manifest_path.exists() {
        return Err(ScaffoldError::ManifestAlreadyExists {
            path: manifest_path,
        });
    }

    let mut files_created = Vec::new();

    let manifest_body = render_manifest(name.as_str(), request.kind);
    write_new_file(&manifest_path, manifest_body.as_bytes())?;
    files_created.push(manifest_path);

    let src_dir = request.dest_dir.join("src");
    create_dir_all(&src_dir)?;

    match request.kind {
        ScaffoldKind::Binary => {
            let main_cc = src_dir.join("main.cc");
            if !main_cc.exists() {
                write_new_file(&main_cc, BINARY_MAIN_CC_TEMPLATE.as_bytes())?;
                files_created.push(main_cc);
            }
        }
        ScaffoldKind::Library => {
            let stems = LibraryStems::from_package_name(name.as_str());
            let include_root = request.dest_dir.join("include");
            let include_pkg_dir = include_root.join(&stems.include_subdir);
            create_dir_all(&include_pkg_dir)?;

            let header_path = include_pkg_dir.join(&stems.header_filename);
            if !header_path.exists() {
                let header_body = render_library_header(&stems);
                write_new_file(&header_path, header_body.as_bytes())?;
                files_created.push(header_path);
            }

            let src_path = src_dir.join(&stems.source_filename);
            if !src_path.exists() {
                let source_body = render_library_source(&stems);
                write_new_file(&src_path, source_body.as_bytes())?;
                files_created.push(src_path);
            }
        }
    }

    if request.emit_gitignore {
        let gitignore_path = request.dest_dir.join(".gitignore");
        if !gitignore_path.exists() {
            write_new_file(&gitignore_path, GITIGNORE_TEMPLATE.as_bytes())?;
            files_created.push(gitignore_path);
        }
    }

    Ok(ScaffoldReport {
        name,
        kind: request.kind,
        files_created,
    })
}

/// Render the deterministic single-package manifest template for
/// `name` and `kind`.  The template carries a `[package]` section
/// with the supplied name plus a single target wired to the
/// kind-appropriate source layout.
pub fn render_manifest(name: &str, kind: ScaffoldKind) -> String {
    match kind {
        ScaffoldKind::Binary => render_binary_manifest(name),
        ScaffoldKind::Library => render_library_manifest(name),
    }
}

// Cabin has no built-in standard defaults, so the generated
// manifests declare one explicitly for the C++ sources they ship.
fn render_binary_manifest(name: &str) -> String {
    format!(
        "[package]\n\
         name = \"{name}\"\n\
         version = \"0.1.0\"\n\
         cxx-standard = \"c++17\"\n\
         \n\
         [target.{name}]\n\
         type = \"executable\"\n\
         sources = [\"src/main.cc\"]\n"
    )
}

fn render_library_manifest(name: &str) -> String {
    let stems = LibraryStems::from_package_name(name);
    format!(
        "[package]\n\
         name = \"{name}\"\n\
         version = \"0.1.0\"\n\
         cxx-standard = \"c++17\"\n\
         \n\
         [target.{name}]\n\
         type = \"library\"\n\
         sources = [\"src/{src}\"]\n\
         include-dirs = [\"include\"]\n",
        src = stems.source_filename,
    )
}

fn render_library_header(stems: &LibraryStems) -> String {
    format!(
        "#pragma once\n\
         \n\
         namespace {ns} {{\n\
         \n\
         int add(int a, int b);\n\
         \n\
         }}  // namespace {ns}\n",
        ns = stems.namespace,
    )
}

fn render_library_source(stems: &LibraryStems) -> String {
    format!(
        "#include \"{include}\"\n\
         \n\
         namespace {ns} {{\n\
         \n\
         int add(int a, int b) {{\n\
         \x20   return a + b;\n\
         }}\n\
         \n\
         }}  // namespace {ns}\n",
        include = stems.header_include_path,
        ns = stems.namespace,
    )
}

/// Filename / identifier stems used by the library scaffold,
/// derived from the validated package name.
#[derive(Debug, Clone, PartialEq, Eq)]
struct LibraryStems {
    /// Subdirectory under `include/` (matches the package name).
    include_subdir: String,
    /// Header filename: `<package_name>.hpp`.
    header_filename: String,
    /// Implementation filename: `<package_name>.cc`.
    source_filename: String,
    /// Include path used inside the implementation source.
    header_include_path: String,
    /// Identifier for the C++ namespace declaration; see
    /// [`sanitize_identifier`].
    namespace: String,
}

impl LibraryStems {
    fn from_package_name(name: &str) -> Self {
        let namespace = sanitize_identifier(name);
        Self {
            include_subdir: name.to_owned(),
            header_filename: format!("{name}.hpp"),
            source_filename: format!("{name}.cc"),
            header_include_path: format!("{name}/{name}.hpp"),
            namespace,
        }
    }
}

/// Convert a validated package name (lowercase ASCII letters, digits,
/// `_`, `-`) into an identifier that is safe to drop into generated
/// C/C++ source.  The conversion is narrow and deterministic:
///
/// - `-` is mapped to `_`, and a run of `_` collapses to one;
/// - if the first character is an ASCII digit, `lib_` is prepended
///   so the result is a valid C++ identifier (which may not start
///   with a digit);
/// - a C++ keyword gets a trailing `_` (`class` -> `class_`).
///
/// The input is already validated by [`validate_package_name`]
/// (lowercase, starting with a letter or digit), so the output is
/// a non-empty sequence of ASCII letters, digits, and `_` that
/// starts with a letter and never contains `__`, which rules out
/// the identifiers [lex.name] reserves.  Reserved namespace names
/// such as `std` and `posix` pass through unchanged.
fn sanitize_identifier(raw: &str) -> String {
    let mut out = String::new();
    if raw.starts_with(|c: char| c.is_ascii_digit()) {
        out.push_str("lib_");
    }
    for c in raw.chars().map(|c| if c == '-' { '_' } else { c }) {
        if !(c == '_' && out.ends_with('_')) {
            out.push(c);
        }
    }
    if CXX_KEYWORDS.contains(&out.as_str()) {
        out.push('_');
    }
    out
}

/// C++23 keywords and alternative tokens ([lex.key], [lex.digraph]),
/// none of which can name a namespace.
const CXX_KEYWORDS: &[&str] = &[
    "alignas",
    "alignof",
    "and",
    "and_eq",
    "asm",
    "auto",
    "bitand",
    "bitor",
    "bool",
    "break",
    "case",
    "catch",
    "char",
    "char16_t",
    "char32_t",
    "char8_t",
    "class",
    "co_await",
    "co_return",
    "co_yield",
    "compl",
    "concept",
    "const",
    "const_cast",
    "consteval",
    "constexpr",
    "constinit",
    "continue",
    "decltype",
    "default",
    "delete",
    "do",
    "double",
    "dynamic_cast",
    "else",
    "enum",
    "explicit",
    "export",
    "extern",
    "false",
    "float",
    "for",
    "friend",
    "goto",
    "if",
    "inline",
    "int",
    "long",
    "mutable",
    "namespace",
    "new",
    "noexcept",
    "not",
    "not_eq",
    "nullptr",
    "operator",
    "or",
    "or_eq",
    "private",
    "protected",
    "public",
    "register",
    "reinterpret_cast",
    "requires",
    "return",
    "short",
    "signed",
    "sizeof",
    "static",
    "static_assert",
    "static_cast",
    "struct",
    "switch",
    "template",
    "this",
    "thread_local",
    "throw",
    "true",
    "try",
    "typedef",
    "typeid",
    "typename",
    "union",
    "unsigned",
    "using",
    "virtual",
    "void",
    "volatile",
    "wchar_t",
    "while",
    "xor",
    "xor_eq",
];

/// Derive the default package name from a target directory: its final
/// component, ASCII-lowercased (`Boa` -> `boa`), or
/// [`FALLBACK_PACKAGE_NAME`] when the component is missing, non-UTF-8,
/// or not a valid bare package name even after lowercasing.
pub(crate) fn default_package_name_from_dir(dest_dir: &Path) -> String {
    dest_dir
        .file_name()
        .and_then(|s| s.to_str())
        .map(str::to_ascii_lowercase)
        .filter(|name| cabin_core::is_valid_package_base_name(name))
        .unwrap_or_else(|| FALLBACK_PACKAGE_NAME.to_owned())
}

fn validate_package_name(raw: String) -> Result<PackageName, ScaffoldError> {
    let name = PackageName::new(raw)?;
    if name.is_scoped() {
        return Err(ScaffoldError::ScopedName {
            base: name.base_name().to_owned(),
            name: name.into(),
        });
    }
    Ok(name)
}

fn create_dir_all(path: &Path) -> Result<(), ScaffoldError> {
    std::fs::create_dir_all(path).map_err(|source| ScaffoldError::Io {
        path: path.to_path_buf(),
        source,
    })
}

fn write_new_file(path: &Path, body: &[u8]) -> Result<(), ScaffoldError> {
    write_atomic(path, body).map_err(|source| ScaffoldError::Io {
        path: path.to_path_buf(),
        source,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    use assert_fs::TempDir;
    use assert_fs::prelude::*;
    use predicates::prelude::*;

    fn binary_request(dest: &Path) -> ScaffoldRequest<'_> {
        ScaffoldRequest::new(dest).with_name(Some("hello"))
    }

    #[test]
    fn scaffold_library_with_a_keyword_name_emits_valid_cpp_namespace() {
        let root = TempDir::new().unwrap();
        let dir = root.child("Class");
        dir.create_dir_all().unwrap();
        let request = ScaffoldRequest::new(dir.path()).with_kind(ScaffoldKind::Library);
        scaffold(request).unwrap();

        let header = std::fs::read_to_string(dir.child("include/class/class.hpp").path()).unwrap();
        assert!(header.contains("namespace class_ {"), "{header}");
        let src = std::fs::read_to_string(dir.child("src/class.cc").path()).unwrap();
        assert!(src.contains("namespace class_ {"), "{src}");
    }

    #[test]
    fn scaffold_library_with_leading_digit_emits_valid_cpp_namespace() {
        let dir = TempDir::new().unwrap();
        let request = ScaffoldRequest::new(dir.path())
            .with_name(Some("9lives"))
            .with_kind(ScaffoldKind::Library);
        scaffold(request).unwrap();

        let header =
            std::fs::read_to_string(dir.child("include/9lives/9lives.hpp").path()).unwrap();
        assert!(
            header.contains("namespace lib_9lives {"),
            "digit-leading names need an unreserved prefix: {header}"
        );
        let src = std::fs::read_to_string(dir.child("src/9lives.cc").path()).unwrap();
        assert!(src.contains("namespace lib_9lives {"));
    }

    #[test]
    fn sanitize_identifier_never_emits_a_double_underscore() {
        assert_eq!(sanitize_identifier("a--b"), "a_b");
        assert_eq!(sanitize_identifier("a_-_b"), "a_b");
        assert_eq!(sanitize_identifier("9-lives"), "lib_9_lives");
    }

    #[test]
    fn scaffold_binary_creates_manifest_and_main_cc() {
        let dir = TempDir::new().unwrap();
        let report = scaffold(binary_request(dir.path())).unwrap();
        assert_eq!(report.name.as_str(), "hello");
        assert_eq!(report.kind, ScaffoldKind::Binary);

        let manifest_text = std::fs::read_to_string(dir.child("cabin.toml").path()).unwrap();
        assert!(manifest_text.contains("[package]"));
        assert!(manifest_text.contains(r#"name = "hello""#));
        assert!(manifest_text.contains(r#"type = "executable""#));

        let main_cc = std::fs::read_to_string(dir.child("src/main.cc").path()).unwrap();
        assert!(main_cc.contains("int main"));
    }

    #[test]
    fn scaffold_library_creates_header_and_implementation() {
        let dir = TempDir::new().unwrap();
        let request = ScaffoldRequest::new(dir.path())
            .with_name(Some("hello"))
            .with_kind(ScaffoldKind::Library);
        let report = scaffold(request).unwrap();
        assert_eq!(report.name.as_str(), "hello");
        assert_eq!(report.kind, ScaffoldKind::Library);

        let manifest_text = std::fs::read_to_string(dir.child("cabin.toml").path()).unwrap();
        assert!(manifest_text.contains(r#"type = "library""#));
        assert!(manifest_text.contains(r#"sources = ["src/hello.cc"]"#));
        assert!(manifest_text.contains(r#"include-dirs = ["include"]"#));

        let header = std::fs::read_to_string(dir.child("include/hello/hello.hpp").path()).unwrap();
        assert!(header.contains("#pragma once"));
        assert!(header.contains("namespace hello"));
        assert!(header.contains("int add(int a, int b);"));

        let src = std::fs::read_to_string(dir.child("src/hello.cc").path()).unwrap();
        assert!(src.contains(r#"#include "hello/hello.hpp""#));
        assert!(src.contains("namespace hello"));
        assert!(src.contains("return a + b;"));
    }

    #[test]
    fn scaffold_library_sanitizes_hyphenated_namespace() {
        let dir = TempDir::new().unwrap();
        let request = ScaffoldRequest::new(dir.path())
            .with_name(Some("hello-world"))
            .with_kind(ScaffoldKind::Library);
        scaffold(request).unwrap();

        let header =
            std::fs::read_to_string(dir.child("include/hello-world/hello-world.hpp").path())
                .unwrap();
        assert!(header.contains("namespace hello_world"));
        let src = std::fs::read_to_string(dir.child("src/hello-world.cc").path()).unwrap();
        assert!(src.contains(r#"#include "hello-world/hello-world.hpp""#));
        assert!(src.contains("namespace hello_world"));
    }

    #[test]
    fn scaffold_emits_gitignore_when_requested() {
        let dir = TempDir::new().unwrap();
        let request = binary_request(dir.path()).with_gitignore(true);
        scaffold(request).unwrap();

        let body = std::fs::read_to_string(dir.child(".gitignore").path()).unwrap();
        assert!(body.contains("/build/"));
        assert!(body.contains("/dist/"));
        assert!(
            !body.contains("cabin.lock"),
            ".gitignore must not ignore cabin.lock: {body}"
        );
    }

    #[test]
    fn scaffold_does_not_emit_gitignore_when_not_requested() {
        let dir = TempDir::new().unwrap();
        scaffold(binary_request(dir.path())).unwrap();
        dir.child(".gitignore").assert(predicate::path::missing());
    }

    #[test]
    fn scaffold_preserves_existing_gitignore() {
        let dir = TempDir::new().unwrap();
        let gitignore = dir.child(".gitignore");
        gitignore.write_str("# user gitignore\n").unwrap();
        let request = binary_request(dir.path()).with_gitignore(true);
        scaffold(request).unwrap();
        let after = std::fs::read_to_string(gitignore.path()).unwrap();
        assert_eq!(after, "# user gitignore\n");
    }

    #[test]
    fn scaffold_rejects_existing_manifest() {
        let dir = TempDir::new().unwrap();
        dir.child("cabin.toml")
            .write_str("# preexisting\n")
            .unwrap();
        let err = scaffold(binary_request(dir.path())).unwrap_err();
        assert!(matches!(err, ScaffoldError::ManifestAlreadyExists { .. }));
        let displayed = format!("{err}");
        assert!(
            displayed.contains("cabin.toml already exists"),
            "unexpected error display: {displayed}"
        );
    }

    #[test]
    fn scaffold_preserves_existing_main_cc() {
        let dir = TempDir::new().unwrap();
        let main_cc = dir.child("src/main.cc");
        let preexisting = "// user code\n";
        main_cc.write_str(preexisting).unwrap();

        scaffold(binary_request(dir.path())).unwrap();
        let after = std::fs::read_to_string(main_cc.path()).unwrap();
        assert_eq!(after, preexisting);
    }

    #[test]
    fn scaffold_library_preserves_existing_header_and_source() {
        let dir = TempDir::new().unwrap();
        let header = dir.child("include/hello/hello.hpp");
        let source = dir.child("src/hello.cc");
        let preexisting_header = "// user header\n";
        let preexisting_source = "// user source\n";
        header.write_str(preexisting_header).unwrap();
        source.write_str(preexisting_source).unwrap();

        let request = ScaffoldRequest::new(dir.path())
            .with_name(Some("hello"))
            .with_kind(ScaffoldKind::Library);
        scaffold(request).unwrap();

        let after_header = std::fs::read_to_string(header.path()).unwrap();
        let after_source = std::fs::read_to_string(source.path()).unwrap();
        assert_eq!(after_header, preexisting_header);
        assert_eq!(after_source, preexisting_source);
    }

    #[test]
    fn scaffold_rejects_invalid_explicit_names() {
        let dir = TempDir::new().unwrap();
        for raw in ["", "foo bar", "foo.bar", "-foo", "_foo"] {
            let err = scaffold(binary_request(dir.path()).with_name(Some(raw))).unwrap_err();
            assert!(matches!(err, ScaffoldError::InvalidName(_)), "{raw:?}");
        }
        assert!(!dir.child(MANIFEST_FILENAME).exists());
    }

    /// An explicit name is an identity the user typed: it is rejected,
    /// never lowercased, and the diagnostic offers the lowercase form.
    #[test]
    fn scaffold_rejects_an_uppercase_explicit_name_with_a_suggestion() {
        let dir = TempDir::new().unwrap();
        let err = scaffold(binary_request(dir.path()).with_name(Some("Boa"))).unwrap_err();
        assert!(matches!(err, ScaffoldError::InvalidName(_)));
        assert!(err.to_string().contains("did you mean \"boa\"?"), "{err}");
    }

    #[test]
    fn scaffold_rejects_a_scoped_explicit_name() {
        let dir = TempDir::new().unwrap();
        let err = scaffold(binary_request(dir.path()).with_name(Some("acme/foo"))).unwrap_err();
        assert!(
            matches!(&err, ScaffoldError::ScopedName { base, .. } if base == "foo"),
            "{err}"
        );
    }

    #[test]
    fn scaffold_uses_directory_name_by_default() {
        let parent = TempDir::new().unwrap();
        let child = parent.child("derived-name");
        child.create_dir_all().unwrap();
        let report = scaffold(ScaffoldRequest::new(child.path())).unwrap();
        assert_eq!(report.name.as_str(), "derived-name");
    }

    /// Only a name inferred from the directory is lowercased; the
    /// directory itself keeps its spelling.
    #[test]
    fn scaffold_lowercases_the_directory_name() {
        for (dir_name, expected) in [("Boa", "boa"), ("MyProject", "myproject")] {
            let parent = TempDir::new().unwrap();
            let child = parent.child(dir_name);
            child.create_dir_all().unwrap();
            let report = scaffold(ScaffoldRequest::new(child.path())).unwrap();
            assert_eq!(report.name.as_str(), expected);
            child
                .child(MANIFEST_FILENAME)
                .assert(predicate::str::contains(format!("name = \"{expected}\"")));
        }
    }

    #[test]
    fn scaffold_falls_back_when_directory_name_unusable() {
        for dir_name in [".dotted", "foo.bar", "-dash", "_under"] {
            let parent = TempDir::new().unwrap();
            let child = parent.child(dir_name);
            child.create_dir_all().unwrap();
            let report = scaffold(ScaffoldRequest::new(child.path())).unwrap();
            assert_eq!(report.name.as_str(), FALLBACK_PACKAGE_NAME, "{dir_name:?}");
        }
    }

    #[test]
    fn scaffold_report_lists_files_in_deterministic_order() {
        let dir = TempDir::new().unwrap();
        let request = ScaffoldRequest::new(dir.path())
            .with_name(Some("hello"))
            .with_kind(ScaffoldKind::Library)
            .with_gitignore(true);
        let report = scaffold(request).unwrap();

        let suffixes: Vec<String> = report
            .files_created
            .iter()
            .map(|p| {
                p.strip_prefix(dir.path())
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/")
            })
            .collect();
        assert_eq!(
            suffixes,
            vec![
                "cabin.toml".to_string(),
                "include/hello/hello.hpp".to_string(),
                "src/hello.cc".to_string(),
                ".gitignore".to_string(),
            ]
        );
    }
}
